import {LinkButton, Link, Banner} from '@primer/react'
import type React from 'react'
import {createPortal} from 'react-dom'
import {useDismissUpsellBanner} from './hooks'
import type {UpsellData} from './types'

interface UpsellBannerProps extends UpsellData {
  repositoryURL: string
  isPullRequestOpen?: boolean
}

export const UpsellBanner: React.FC<UpsellBannerProps> = ({
  repositoryURL,
  isPullRequestOpen,
  urls,
  plan,
  upsellPlan,
  isAdmin,
  quotaReset,
  overagesVisible,
  overagesEnabled,
  bannerDismissKey,
}) => {
  const {container, isDismissed, handleDismiss} = useDismissUpsellBanner(repositoryURL, bannerDismissKey)

  if (!container || isDismissed) return null
  return createPortal(
    <Banner
      title="You're out of premium requests"
      hideTitle
      variant="upsell"
      onDismiss={handleDismiss}
      className={isPullRequestOpen ? 'tmp-mb-3' : 'tmp-my-3'}
    >
      <span>
        You have reached your monthly limit for{' '}
        <Link inline target="_blank" rel="noopener noreferrer" href={urls.docs}>
          premium requests
        </Link>{' '}
        for Copilot code review.{' '}
        {!isAdmin && plan !== 'individual' && 'Ask your admin to upgrade to increase your limit. '}
        Limit resets on {quotaReset.date}.
      </span>
      {(isAdmin || plan === 'individual') && (
        <div className="d-flex mt-2">
          {!!(urls.upsell && upsellPlan) && (
            <LinkButton target="_blank" rel="noopener noreferrer" href={urls.upsell} className="mr-2">
              Upgrade to {upsellPlan}
            </LinkButton>
          )}
          {overagesVisible && (
            <LinkButton
              target="_blank"
              rel="noopener noreferrer"
              href={overagesEnabled ? urls.billing : urls.policy}
              variant={urls.upsell ? 'invisible' : 'default'}
            >
              {overagesEnabled ? 'Manage billing' : 'Enable additional requests'}
            </LinkButton>
          )}
        </div>
      )}
    </Banner>,
    container,
  )
}
